style.css:
/* Roblox 2008 Classic Theme for Stylish */

@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("roblox.com") {
/* === BACKGROUND & FONT === */
  body, html {
    background-color: #c2c2c2 !important;
    font-family: Verdana, sans-serif !important;
    color: black !important;
  }

  /* === HEADER === */
  .navbar, .navigation-bar, .header {
    background-color: #343434 !important;
    border-bottom: 3px solid #ffd800 !important;
    color: white !important;
  }

  .navbar a, .header a {
    color: white !important;
    font-weight: bold;
  }

  /* === BUTTONS === */
  button, .btn-primary, .btn-secondary {
    background-color: #ffd800 !important;
    border: 2px solid #000 !important;
    color: black !important;
    font-weight: bold;
  }

  /* === SIDEBAR / NAVIGATION === */
  .left-nav, .nav-menu, .menu-vertical {
    background-color: #a9a9a9 !important;
    color: black !important;
  }

  /* === GAME THUMBNAILS === */
  .game-card, .thumbnail, .game-tile {
    border: 2px solid #000 !important;
    background-color: #e1e1e1 !important;
  }

  /* === AVATAR ICON === */
  .avatar-card-image, .avatar-icon {
    border: 2px solid black !important;
    background-color: white !important;
  }

  /* === TEXTBOXES / FORMS === */
  input, textarea, select {
    background-color: white !important;
    border: 2px solid #000 !important;
    color: black !important;
  }

  /* === REMOVE MODERN ANIMATIONS === */
  * {
    transition: none !important;
    animation: none !important;
  }

  /* === FOOTER === */
  .footer, .footer-container {
    background-color: #343434 !important;
    color: white !important;
  }

  /* === ICONS COLOR FIX === */
  svg, .icon {
    fill: black !important;
  }
}
